// --- 1. Initialization ---
// Fetch live reports from Supabase and merge with demo data (demo remains as secondary). No localStorage fallback.
async function loadReportsFromSupabase() {
  // If Supabase client not present, keep demo-only state
  if (!window.supabaseClient) {
    console.warn('Supabase client not found on window; using demo data only.');
    return;
  }

  try {
    // Select recent reports; adjust column names to match your table
    const { data, error } = await window.supabaseClient
      .from('reports')
      .select('*')
      .order('submitted_at', { ascending: false });

    if (error) {
      console.error('Error fetching reports from Supabase:', error);
      showToast('Data Load Error', 'Unable to fetch live reports from Supabase. Showing demo data.');
      return;
    }

    if (!data || data.length === 0) {
      console.info('No reports returned from Supabase; keeping demo data.');
      return;
    }

    // Map Supabase rows to application issue objects
    const liveReports = data.map(function (r, idx) {
      return {
        id: r.request_id || r.id || ('CP-REQ-SUP-' + (idx + 1)),
        citizenName: r.citizen_name || r.citizenName || 'Anonymous Citizen',
        title: r.title || (r.category ? (r.category + ' in ' + r.area) : 'Citizen Report'),
        category: r.category || r.category_name || 'General',
        area: r.area || 'Unknown Area',
        description: r.description || '',
        peopleAffected: r.people_affected != null ? r.people_affected : (r.peopleAffected || 1),
        severity: r.severity || 'Medium',
        priority: r.priority || 'Medium',
        priorityReason: r.priority_reason || '',
        communitySupport: r.community_support != null ? r.community_support : (r.communitySupport || 1),
        isDemo: false,
        status: r.status || 'Pending',
        suggestedAction: r.suggested_action || r.suggestedAction || 'Forwarded to ward inspection division for field assessment.',
        submittedAt: r.submitted_at || r.submittedAt || new Date().toISOString()
      };
    });

    // Replace state.issues so live reports are shown first, but keep demo data after
    state.issues = liveReports.concat(demoIssues.slice());
    console.info('Loaded', liveReports.length, 'reports from Supabase.');
  } catch (err) {
    console.error('Unexpected error loading Supabase reports:', err);
    showToast('Data Load Error', 'Unexpected error fetching live reports. Check console for details.');
  }
}

async function init() {
  populateDropdowns();
  // Load live reports (if available) to replace the demo-only placeholder
  await loadReportsFromSupabase();
  // Rebuild area filter list based on loaded reports
  restoreCustomAreas();
  renderIssuesTable();
  updateGovernmentDashboard();
  setupEventListeners();
}

