// js/hotspotAnalysis.js

(function () {
  // This module exposes a render function to be called from app.js
  window.renderDemandHotspotAnalysis = function (areaStats) {
    // Find or create analysis container in the dashboard area
    var container = document.getElementById('hotspotAnalysisContainer');
    if (!container) {
      // create a new minimal container below the existing hotspotsContainer
      var hotspotsParent = document.getElementById('hotspotsContainer');
      if (!hotspotsParent) return; // cannot find place to attach

      container = document.createElement('div');
      container.id = 'hotspotAnalysisContainer';
      container.style.marginTop = '16px';
      container.style.padding = '12px';
      container.style.background = '#fbfbff';
      container.style.border = '1px solid #e6e9ff';
      container.style.borderRadius = '8px';
      container.style.fontSize = '14px';

      hotspotsParent.parentNode.insertBefore(container, hotspotsParent.nextSibling);
    }

    // Convert areaStats to array and compute dominant category + overall priority
    var rows = [];
    for (var area in areaStats) {
      var stats = areaStats[area];
      // determine dominant category
      var topCat = 'N/A';
      var topCatCount = 0;
      for (var c in stats.categories) {
        if (stats.categories[c] > topCatCount) {
          topCatCount = stats.categories[c];
          topCat = c;
        }
      }

      // determine overall priority: the highest priority with at least 1 report, ordered Critical > High > Medium > Low
      var overall = 'Low';
      if (stats.priorityCounts && stats.priorityCounts.Critical > 0) overall = 'Critical';
      else if (stats.priorityCounts && stats.priorityCounts.High > 0) overall = 'High';
      else if (stats.priorityCounts && stats.priorityCounts.Medium > 0) overall = 'Medium';

      rows.push({
        area: area,
        count: stats.count,
        totalPeople: stats.totalPeople,
        topCategory: topCat,
        overallPriority: overall
      });
    }

    rows.sort(function (a, b) { return b.count - a.count; });

    // Render top 6 areas
    var html = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">'
             + '<strong>Demand Hotspot Analysis</strong>'
             + '<span style="font-size:12px;color:#666;">Grouped by area: top areas ranked by report count</span>'
             + '</div>';

    html += '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px">';
    rows.slice(0, 6).forEach(function (r) {
      html += '<div style="padding:10px;border-radius:6px;background:#fff;border:1px solid #eaeefb;">'
           + '<div style="font-weight:600;color:#1e3a8a;margin-bottom:6px;">' + escapeHtml(r.area) + '</div>'
           + '<div style="font-size:13px;color:#333;margin-bottom:4px;">' + r.count + ' reports &bull; 👥 ~' + (r.totalPeople || 0) + ' people</div>'
           + '<div style="font-size:12px;color:#666;">Dominant: <strong>' + escapeHtml(r.topCategory || 'N/A') + '</strong></div>'
           + '<div style="margin-top:6px;font-size:12px;">Overall Priority: <span style="font-weight:700">' + escapeHtml(r.overallPriority) + '</span></div>'
           + '</div>';
    });
    html += '</div>';

    container.innerHTML = html;

    function escapeHtml(u) {
      if (!u) return ''; return u.toString()
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
    }
  };
})();
